const notifier=()=>{const e=document.getElementById("notification");let n;return{notify:function(t,o=1e3){!e||!t||(n&&clearTimeout(n),e.innerHTML=t,e.style.zIndex=15,e.style.top=0,n=window.setTimeout(()=>{e.style.top="-4em",e.style.zIndex=-1,window.setTimeout(()=>{e.innerHTML=""},1e3),n=void 0},o))}}},serviceWorkerSetup=async()=>{if(!("serviceWorker"in navigator)){document.querySelectorAll(".pwa").forEach(t=>{t.remove()});return}const n=(await navigator.serviceWorker.getRegistrations()).map(t=>t.unregister());await Promise.all(n),navigator.serviceWorker.register("/static/js/serviceworker.js",{start_url:"/",scope:"/"}).then(()=>console.log("Service Worker registered")).catch(t=>console.error("Service Worker registration failed",t))},home=()=>{const e=document.querySelector("#new-room form .phantom"),n=e.getAttribute("title"),t=document.getElementById("phantom"),o=document.getElementById("unlisted");if(serviceWorkerSetup(),!e||!n||!t||!o)return;const r=()=>{t.checked&&o.checked?e.setAttribute("title","Phantom & unlisted room"):e.setAttribute("title",n)};t.addEventListener("change",r),o.addEventListener("change",r);const i=notifier();document.querySelectorAll(".pwa").forEach(s=>{const c='<a href="https://developer.mozilla.org/en-US/docs/Web/Progressive_web_apps/Guides/Installing" target="_blank">Check how to install PWA</a>';s.addEventListener("click",()=>{i.notify(c,3e3)})})};home();
